import {lessons as allLessons,units,RELEASED_UNITS,isReleased,STORAGE_KEY,sanitizeProgress,nextLesson,canOpen as lockOpen,complete,checkpointOf,unitPassed,grade} from './model.mjs';
import {TR,TR_LESSONS,TR_UNITS,TR_MISSIONS} from './i18n.mjs';
import {MISSIONS,checkGoals} from './missions.mjs';
import {Lab} from './lab.mjs';

import {resolveDiagram} from './sim/circuit.mjs';
// only released units count as lessons on the public site
const lessons=allLessons.filter(isReleased);
const $=s=>document.querySelector(s);const app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const VERSION='1.0',LANG_KEY='pin-by-pin-lang',WORK_KEY='pin-by-pin-work-v1',PROJ_KEY='pin-by-pin-projects-v1';
let storageOK=true,p,lang='en';
try{p=sanitizeProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'));}catch{p=sanitizeProgress({});storageOK=false;}
try{if(localStorage.getItem(LANG_KEY)==='tr')lang='tr';}catch{}
const canOpen=lockOpen;
// English is the source text; TR maps it to Turkish. {name} placeholders are filled from v.
const t=(s,v={})=>{let r=lang==='tr'&&TR[s]||s;for(const k in v)r=r.split('{'+k+'}').join(v[k]);return r;};
const L=l=>{const tr=lang==='tr'&&TR_LESSONS[l.id];return tr?{...l,...tr,questions:l.questions?.map((q,i)=>({...q,...tr.questions?.[i]}))}:l;};
const U=u=>lang==='tr'&&TR_UNITS[u.id]?{...u,...TR_UNITS[u.id]}:u;
// mission text: English in missions.mjs, Turkish in TR_MISSIONS (same shape, goals and steps by index)
const M=id=>{const m=MISSIONS[id];const tr=lang==='tr'&&TR_MISSIONS[id];return {title:tr?.title||m.title,intro:tr?.intro||m.intro,steps:tr?.steps||m.steps,hints:tr?.hints||m.hints,goals:m.goals.map((g,i)=>tr?.goals?.[i]||g.text)};};
const title=l=>l.type==='mission'?M(l.id).title:L(l).title;
const sk=code=>lang==='tr'?code.replace(/\/\/ (.*)$/gm,(_,c)=>'// '+t(c)):code;
const md=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>');
const load=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??d;}catch{return d;}};
const store=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{storageOK=false;}};
let view='home',lesson=null,selected=null,checked=false,hint=false,cps={},toastTimer,lab=null,ms={};
const icon=(name)=>{const shapes={path:'<path d="M4 17h6V7h10M4 7h3m10 10h3"/><circle cx="4" cy="17" r="2"/><circle cx="20" cy="7" r="2"/>',lab:'<path d="M8 3h8M10 3v7l-6 10h16l-6-10V3M7 15h10"/>',book:'<path d="M5 3h14v18H5zM9 3v18M12 8h4m-4 4h4"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',check:'<path d="m5 12 5 5L20 7"/>',lock:'<rect x="6" y="10" width="12" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',flag:'<path d="M5 21V4m0 0h11l-2 4 2 4H5"/>',quiz:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.6V14m0 3h.01"/>',build:'<path d="M14 4l6 6-9 9H5v-6z"/><path d="M12 6l6 6"/>',star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.chip}</svg>`;};
const brand=()=>`<a class="brand" href="#/" data-home aria-label="${t('Pin by Pin Lab home')}"><svg viewBox="0 0 40 46" fill="none" aria-hidden="true"><rect x="6" y="7" width="28" height="32" rx="5" stroke="currentColor" stroke-width="1.5"/><path d="M13 31V15h8a6 6 0 0 1 0 12h-8M3 15h3m-3 8h3m-3 8h3m28-16h3m-3 8h3m-3 8h3M15 4v3m10-3v3m-10 32v3m10-3v3" stroke="currentColor" stroke-width="1.5"/></svg><span>pin by pin<small>LEARNING LAB</small></span></a>`;
const langSwitch=()=>`<div class="lang-switch" role="group" aria-label="Language / Dil">${['en','tr'].map(l=>`<button data-lang="${l}" class="${lang===l?'active':''}" aria-pressed="${lang===l}" lang="${l}" title="${l==='en'?'English':'Türkçe'}">${l.toUpperCase()}</button>`).join('')}</div>`;
function applyLang(){document.documentElement.lang=lang;document.title=t('Pin by Pin Lab — It starts with a pin.');const s=$('.skip');if(s)s.textContent=t('Skip to content');$('meta[name=description]')?.setAttribute('content',t('Write real Arduino code, wire a circuit and run it in your browser. Free ESP32 lessons based on ESP32 From Zero.'));}
function setLang(l){lang=l;try{localStorage.setItem(LANG_KEY,l);}catch{}applyLang();render();}
function announce(text){$('#announcer').textContent=text;}
function toast(text){document.querySelector('.toast')?.remove();clearTimeout(toastTimer);const d=document.createElement('div');d.className='toast';d.textContent=text;d.setAttribute('role','status');document.body.append(d);toastTimer=setTimeout(()=>d.remove(),4000);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(p));}catch{storageOK=false;toast(t('Couldn’t save. You can download your progress from My notebook.'));}}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function shell(content,wide=false){return `<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="${t('Main menu')}">${[['home','path','Learning path'],['workshop','lab','Workshop'],['notebook','book','My notebook']].map(([v,i,s])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} title="${t(s)}" aria-label="${t(s)}">${icon(i)}<span>${t(s)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="free">${t('Free for everyone.')}</div><p>${t('No kit yet?<br>You can still start.')}</p><a href="https://github.com/emjnbulut/esp32-from-zero" target="_blank" rel="noopener">ESP32 From Zero ↗</a></div></aside><main id="main" class="main${wide?' wide':''}"><header class="topbar"><div class="crumb">${t('WORKSHOP')} / <strong>ESP32</strong></div><div class="stats"><span class="stat-tasks"><b>${p.completed.length}</b> / ${lessons.length} ${t('tasks')}</span>${langSwitch()}</div></header>${!storageOK?`<div class="storage-warning">${t('Browser storage is unavailable. You can download your progress as a file from My notebook.')}</div>`:''}${content}<footer class="footer"><span>${t('PIN BY PIN LAB · Together, step by step.')}</span><span>${t('Based on the ESP32 From Zero curriculum · Version {v}',{v:VERSION})}</span></footer></main></div>`;}
function heroArt(){return `<svg viewBox="0 0 460 300" fill="none" role="img" aria-label="${t('A code editor next to an ESP32 circuit with a glowing LED')}"><rect x="10" y="30" width="200" height="230" rx="10" fill="#1e2a25"/><rect x="10" y="30" width="200" height="26" rx="10" fill="#19231f"/><circle cx="28" cy="43" r="4" fill="#ff6b5b"/><circle cx="42" cy="43" r="4" fill="#ffc94a"/><circle cx="56" cy="43" r="4" fill="#5cd67a"/>
 <g font-family="monospace" font-size="10"><text x="24" y="80" fill="#7fc7ff">void <tspan fill="#e5f292">loop</tspan><tspan fill="#d8e3dc">() {</tspan></text><text x="36" y="100" fill="#e5f292">digitalWrite<tspan fill="#d8e3dc">(23, </tspan><tspan fill="#7fc7ff">HIGH</tspan><tspan fill="#d8e3dc">);</tspan></text><text x="36" y="118" fill="#e5f292">delay<tspan fill="#d8e3dc">(</tspan><tspan fill="#ffb86b">500</tspan><tspan fill="#d8e3dc">);</tspan></text><text x="36" y="136" fill="#e5f292">digitalWrite<tspan fill="#d8e3dc">(23, </tspan><tspan fill="#7fc7ff">LOW</tspan><tspan fill="#d8e3dc">);</tspan></text><text x="36" y="154" fill="#e5f292">delay<tspan fill="#d8e3dc">(</tspan><tspan fill="#ffb86b">500</tspan><tspan fill="#d8e3dc">);</tspan></text><text x="24" y="172" fill="#d8e3dc">}</text></g>
 <rect x="24" y="214" width="78" height="28" rx="6" fill="#2f9a3c"/><text x="63" y="232" text-anchor="middle" fill="#fff" font-size="11" font-family="sans-serif" font-weight="700">▶ Run</text>
 <rect x="250" y="60" width="72" height="150" rx="6" fill="#1d2a38"/><rect x="262" y="66" width="48" height="36" rx="2" fill="#c9ced6"/><text x="286" y="160" text-anchor="middle" fill="#e3e9ef" font-size="9" font-family="sans-serif" font-weight="700">ESP32</text>${Array.from({length:10},(_,i)=>`<rect x="246" y="${108+i*9}" width="6" height="4" fill="#d6b45a"/><rect x="320" y="${108+i*9}" width="6" height="4" fill="#d6b45a"/>`).join('')}
 <path d="M326 110H372V150" stroke="#2f9a3c" stroke-width="3" fill="none"/><rect x="364" y="150" width="16" height="34" rx="5" fill="#d9c08f"/><path d="M372 184V200H400" stroke="#9a9a9a" stroke-width="2.4"/><circle cx="410" cy="150" r="36" fill="#ff4d3a" opacity=".22"/><path d="M398 196V162a12 12 0 0 1 24 0v34z" fill="#ff4d3a"/><path d="M422 196V230H326" stroke="#2b2b2b" stroke-width="3" fill="none"/></svg>`;}
function nodeIcon(l,done,open){return icon(done?'check':!open?'lock':l.type==='mission'?(l.tag==='CHALLENGE'?'star':l.tag==='YOUR TURN'?'chip':'build'):'quiz');}
function home(){const next=nextLesson(p);return shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('WRITE. WIRE. RUN.')}</div><h1>${t('It starts<br><em>with a pin.</em>')}</h1><p>${t('Write real Arduino code, wire the circuit and press Run. Everything happens in your browser: no kit, no installation. Every unit follows an ESP32 From Zero episode.')}</p><div class="hero-actions"><button class="primary" ${next?`data-lesson="${next.id}"`:'data-nav="workshop"'}>${p.completed.length?t('Continue'):t('Start the first project')} <span>→</span></button><button class="secondary" data-nav="workshop">${t('Open the free workshop')}</button></div></div><div class="hero-art">${heroArt()}</div></section>
 <div class="dashboard"><section aria-label="${t('Learning path')}"><div class="section-label"><strong>${t('YOUR LEARNING PATH')}</strong><span>${t('BUILD FIRST · QUIZZES IN BETWEEN')}</span></div>${units.filter(u=>RELEASED_UNITS.includes(u.id)).map(U).map(u=>{const ls=lessons.filter(l=>l.unit===u.id&&l.type!=='checkpoint'),count=ls.filter(l=>p.completed.includes(l.id)).length,passed=unitPassed(u.id,p);
  return `<article class="unit ${next?.unit===u.id?'current':''}"><div class="unit-head"><span class="unit-num">0${u.id}</span><div><h3>${u.title}</h3><p>${u.subtitle}</p></div><span class="unit-status">${passed&&count<ls.length?t('PASSED'):count===ls.length?t('COMPLETED'):`${count} / ${ls.length}`}</span></div>
  <div class="steps-path">${ls.map(l=>{const done=p.completed.includes(l.id),open=canOpen(l.id,p),active=next?.id===l.id;return `<button class="lesson-node ${l.type}${l.tag==='YOUR TURN'?' yourturn':''} ${done?'done':''} ${active?'next':''}" data-lesson="${l.id}" ${open?'':'disabled'} aria-label="${esc(title(l))}${done?t(', completed'):!open?t(', complete the previous tasks first'):''}"><span class="node-icon">${nodeIcon(l,done,open)}</span><span class="node-text"><span class="node-kind">${l.type==='mission'?(l.tag==='CHALLENGE'?t('CHALLENGE'):l.tag==='YOUR TURN'?t('YOUR TURN'):t('BUILD')):t('QUIZ')}${active?` · <em>${t('NEXT STEP')}</em>`:''}</span><span class="node-title">${title(l)}</span><span class="node-meta">${l.minutes} ${t('MIN')}</span></span></button>`;}).join('')}</div>${checkBar(checkpointOf(u.id))}</article>`;}).join('')}
  <div class="section-label"><strong>${t('COMING UP')}</strong><span>${t('CURRICULUM · IN PROGRESS')}</span></div>${units.filter(u=>!RELEASED_UNITS.includes(u.id)).map(U).map(u=>`<div class="upcoming"><span class="unit-num">${String(u.id).padStart(2,'0')}</span><div><h3>${u.title}</h3><p>${u.subtitle}</p></div><span>${t('WAITING FOR THE VIDEO')}</span></div>`).join('')}</section>
 <aside><div class="continue-card"><div class="eyebrow">${p.completed.length?t('PICK UP WHERE YOU LEFT OFF'):t('YOUR FIRST STEP IS READY')}</div><h2>${next?title(next):t('Every open task is done.')}</h2><p>${next?t('A few minutes, a new discovery. You don’t need a kit to keep going.'):t('You have completed every open task. Try different connections in the workshop.')}</p><button class="primary" ${next?`data-lesson="${next.id}"`:'data-nav="workshop"'}>${p.completed.length?t('Continue'):t('Start learning')} <span>→</span></button></div>
 <div class="note-card"><div class="eyebrow">${t('HOW IT WORKS')}</div><h3>${t('Build, run, check.')}</h3><p>${t('Each project lists its goals. They are checked live while your circuit runs. Stuck? Open a hint, or look at the solution.')}</p></div>
 <div class="note-card"><div class="eyebrow">${t('SMALL STEPS ADD UP')}</div><div class="tiny-progress"><div style="width:${p.completed.length/lessons.length*100}%"></div></div><div class="progress-caption"><span>${t('{n} tasks completed',{n:p.completed.length})}</span><span>${lessons.length} ${t('TASKS')}</span></div><p style="margin-top:14px">${t('Your progress is saved in this browser.<br>You can download a copy from My notebook.')}</p></div></aside></div>`);}
function checkBar(c){if(!c)return '';const done=p.completed.includes(c.id),open=canOpen(c.id,p);return `<div class="unit-check ${done?'done':''} ${nextLesson(p)?.id===c.id?'next':''}"><span class="check-icon">${icon(done?'check':open?'flag':'lock')}</span><div><strong>${L(c).title}</strong><small>${done?t('Passed · every lesson of this unit is open.'):t('Already know this? Test out: {n} questions, {pass} to pass.',{n:c.questions.length,pass:c.pass})}</small></div><button class="secondary" data-lesson="${c.id}" ${open?'':'disabled'}>${done?t('Retake'):t('Take the checkpoint')}</button></div>`;}
function notebook(){return shell(`<section class="notebook"><div class="eyebrow">${t('YOUR WORKSHOP NOTEBOOK')}</div><h1 style="margin-top:18px">${t('What you’ve learned.')}</h1><p>${t('{n} tasks · you practised on {d} different days.',{n:p.completed.length,d:p.dates.length})}<br>${t('This record lives only in this browser. Download a copy before switching devices.')}</p>${p.completed.length?lessons.filter(l=>p.completed.includes(l.id)).map(l=>`<div class="record"><div><strong>${title(l)}</strong><br><small>${t('UNIT')} ${l.unit}</small></div><button class="secondary" data-lesson="${l.id}">${t('Repeat ↗')}</button></div>`).join(''):`<div class="empty-note">${t('Nothing here yet. Your first task is ready.')}<br><button class="primary" style="margin-top:18px" data-lesson="${lessons[0].id}">${t('Go to the first step ↗')}</button></div>`}<div class="notebook-actions"><button class="secondary" id="export-progress">${t('Download notebook ↓')}</button><button class="secondary" id="import-progress">${t('Load notebook ↑')}</button><button class="secondary" id="reset-progress">${t('Reset progress')}</button><input class="sr-only" type="file" id="progress-file" accept="application/json,.json" aria-label="${t('Progress file')}"></div></section>`);}
function lessonHeader(){const index=lessons.findIndex(l=>l.id===lesson.id);return `<header class="lesson-header"><button class="close" data-nav="home" aria-label="${t('Back to the learning path')}">×</button><span class="mono">${t('UNIT')} 0${lesson.unit}</span><div class="lesson-progress" role="progressbar" aria-label="${t('Task order')}" aria-valuenow="${index+1}" aria-valuemin="0" aria-valuemax="${lessons.length}"><i style="width:${(index+1)/lessons.length*100}%"></i></div><span class="mono">${lesson.minutes} ${t('MIN')}</span>${langSwitch()}</header>`;}
const sourceLink=()=>{const src=units.find(u=>u.id===lesson.unit).source;return `<div class="source">${t('SOURCE OF THIS LESSON')}<br><a target="_blank" rel="noopener" href="https://github.com/emjnbulut/esp32-from-zero/${src?'tree/main/lessons/'+src:'blob/main/CURRICULUM.md'}">ESP32 From Zero · ${t('Episode')} ${lesson.unit}${src?'':' · '+t('video coming soon')} ↗</a></div>`;};
function lessonPage(){if(lesson.type==='mission')return missionPage();const index=lessons.findIndex(l=>l.id===lesson.id),c=L(lesson);return `<div class="lesson-shell">${lessonHeader()}<main id="main" class="lesson-layout"><aside class="lesson-copy"><div class="eyebrow">${c.tag} / ${String(index+1).padStart(2,'0')}</div><h1 class="focus-title" tabindex="-1">${c.title}</h1><p>${c.intro}</p><button class="secondary hint-button" id="hint" aria-expanded="${hint}">${t('A small hint')} ${hint?'−':'+'}</button><p class="hint-text" id="hint-text" ${hint?'':'hidden'}>${c.hint}</p>${sourceLink()}</aside>${lesson.type==='quiz'?quiz():checkpointPage()}</main></div>`;}
function quiz(){const c=L(lesson),offset=lessons.indexOf(lesson)%3;const order=[0,1,2].map(i=>(i+offset)%3);return `<section class="exercise quiz">${c.code?`<div class="code-label">${t('SKETCH.INO / READ AND PREDICT')}</div><pre><code>${esc(sk(c.code))}</code></pre>`:''}<h2>${c.question}</h2><div class="choices" role="group" aria-label="${t('Answer options')}">${order.map((n,i)=>`<button class="choice ${selected===n?'selected':''} ${checked&&n===lesson.answer?'correct':''}" data-choice="${n}" ${checked?'disabled':''} aria-pressed="${selected===n}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${c.choices[n]}</span></button>`).join('')}</div><div class="feedback ${checked?'good':''}" id="feedback" role="status">${checked?c.explanation:''}</div><div class="exercise-bottom"><small>${t('Trying is always allowed.')}</small><button class="primary" id="check-answer" ${selected===null?'disabled':''}>${checked?t('Complete task →'):t('Check →')}</button></div></section>`;}
const fmt=n=>lang==='tr'?String(n).replace('.',','):String(n);
const cpOrder=(q,i)=>{const k=q.choices.length,s=(i+lessons.indexOf(lesson))%k;return q.choices.map((_,n)=>(n+s)%k);};
function checkpointPage(){const c=L(lesson),qs=c.questions,res=cps.graded?grade(lesson.questions,cps.answers):null,score=res?res.filter(Boolean).length:0,passed=!!res&&score>=lesson.pass;
 return `<section class="exercise quiz checkpoint"><div class="workbench-top"><div class="eyebrow">${t('UNIT CHECKPOINT')}</div><span class="model-tag">${t('PASS: {pass} / {n}',{pass:lesson.pass,n:qs.length})}</span></div>${qs.map((q,i)=>`<div class="cp-q ${res?(res[i]?'good':'bad'):''}"><div class="cp-num">${i+1} / ${qs.length}</div><h3>${q.q}</h3>${q.code?`<pre><code>${esc(sk(q.code))}</code></pre>`:''}${q.choices?`<div class="choices" role="group" aria-label="${t('Answer options')}">${cpOrder(q,i).map((n,pos)=>`<button class="choice ${cps.answers[i]===n?'selected':''} ${res&&n===q.answer?'correct':''}" data-cp-choice="${i}-${n}" ${res?'disabled':''} aria-pressed="${cps.answers[i]===n}"><span class="letter">${String.fromCharCode(65+pos)}</span><span>${q.choices[n]}</span></button>`).join('')}</div>`:`<label class="cp-input"><input type="text" inputmode="decimal" autocomplete="off" data-cp-input="${i}" value="${esc(cps.answers[i]??'')}" ${res?'disabled':''} placeholder="${t('Your answer')}" aria-label="${t('Your answer')}">${q.unit?`<span>${t(q.unit)}</span>`:''}</label>`}${res?`<p class="cp-explain">${res[i]?'✓ ':'✗ '+t('Answer: {a}',{a:q.choices?q.choices[q.answer]:fmt(q.answer)+(q.unit?' '+t(q.unit):'')})+'<br>'}${q.explain}</p>`:''}</div>`).join('')}<div class="feedback ${res?(passed?'good':'bad'):''}" id="feedback" role="status">${res?(passed?t('{s} / {n} correct. Checkpoint passed!',{s:score,n:qs.length}):t('{s} / {n} correct. You need {pass}. Read the explanations and try again.',{s:score,n:qs.length,pass:lesson.pass})):''}</div><div class="exercise-bottom"><small>${t('Numbers: a comma or a dot both work.')}</small><button class="primary" id="cp-submit">${!res?t('Check answers →'):passed?t('Complete checkpoint →'):t('Try again')}</button></div></section>`;}
// ---------- missions ----------
// a "your turn" task starts from the learner's own work on its parent mission when there is some
function work(id){const all=load(WORK_KEY,{});const w=all[id];const m=MISSIONS[id];if(w?.code!==undefined)return w;const pw=m.parent&&all[m.parent];if(pw?.code!==undefined)return {code:pw.code,diagram:pw.diagram};return {code:sk(m.starter.code),diagram:m.starter.diagram};}
function saveWork(id,state){const all=load(WORK_KEY,{});all[id]={code:state.code,diagram:state.diagram};store(WORK_KEY,all);}
function missionPage(){const c=M(lesson.id),index=lessons.findIndex(l=>l.id===lesson.id);
 return `<div class="lesson-shell mission-shell">${lessonHeader()}<main id="main" class="mission-layout"><aside class="mission-panel"><div class="eyebrow">${lesson.tag==='CHALLENGE'?t('CHALLENGE'):lesson.tag==='YOUR TURN'?t('YOUR TURN'):t('BUILD')} / ${String(index+1).padStart(2,'0')}</div><h1 class="focus-title" tabindex="-1">${esc(c.title)}</h1><p class="mission-intro">${md(c.intro)}</p>
  <ol class="mission-steps">${c.steps.map(s=>`<li>${md(s)}</li>`).join('')}</ol>
  <div class="goals"><div class="code-label">${t('GOALS · CHECKED WHILE IT RUNS')}</div>${c.goals.map((g,i)=>`<div class="goal ${ms.passed?.[i]?'ok':''}" data-goal="${i}"><span class="tick" aria-hidden="true">${ms.passed?.[i]?'✓':''}</span><span>${md(g)}</span><span class="sr-only">${ms.passed?.[i]?t('done'):t('not yet')}</span></div>`).join('')}</div>
  <div class="mission-feedback" id="mission-feedback" role="status">${ms.done?t('All goals reached. Well done!'):''}</div>
  <button class="primary mission-done" id="mission-done" ${ms.done?'':'disabled'}>${t('Complete project →')}</button>
  <div class="mission-help"><button class="secondary" id="hint-next" ${ms.hints>=c.hints.length?'disabled':''}>${t('Show a hint ({i} / {n})',{i:Math.min(ms.hints+1,c.hints.length),n:c.hints.length})}</button><div id="hints">${c.hints.slice(0,ms.hints).map(h=>`<p class="hint-text">${md(h)}</p>`).join('')}</div>
   <div class="mission-tools"><button class="lab-link" id="show-solution">${t('Load the solution')}</button><button class="lab-link" id="reset-work">${t('Start over')}</button></div></div>${sourceLink()}</aside>
  <section class="mission-lab" id="lab-root"></section></main></div>`;}
function updateGoals(){const c=M(lesson.id);document.querySelectorAll('[data-goal]').forEach(el=>{const i=Number(el.dataset.goal),ok=!!ms.passed?.[i];el.classList.toggle('ok',ok);el.querySelector('.tick').textContent=ok?'✓':'';el.querySelector('.sr-only').textContent=ok?t('done'):t('not yet');});
 const all=ms.passed&&ms.passed.length===c.goals.length&&ms.passed.every(Boolean);if(all&&!ms.done){ms.done=true;$('#mission-done').disabled=false;$('#mission-feedback').textContent=t('All goals reached. Well done!');announce(t('All goals reached. Well done!'));}}
function mountMissionLab(){const id=lesson.id,m=MISSIONS[id],w=work(id);lab?.destroy();
 lab=new Lab({t,code:w.code,diagram:w.diagram,onChange:st=>saveWork(id,st),onTick:s=>{if(s.status!=='running'&&!s.passed)return;ms.passed=checkGoals(m,s);updateGoals();},onRun:on=>{if(on){ms.passed=m.goals.map(()=>false);updateGoals();}}});
 lab.mount($('#lab-root'));}
// ---------- workshop (free projects) ----------
const blankProject=()=>({id:'p'+Date.now().toString(36)+Math.floor(Math.random()*1e4),name:t('My project'),code:'void setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n}\n',diagram:resolveDiagram({parts:[{id:'esp',type:'esp32',x:0,y:0},{id:'bb',type:'breadboard',x:160,y:0}],wires:[]})});
function projects(){let ps=load(PROJ_KEY,null);if(!ps||!ps.list?.length){const first={...blankProject(),name:'Blink',code:MISSIONS.blink.solution.code,diagram:MISSIONS.blink.solution.diagram};ps={current:first.id,list:[first]};store(PROJ_KEY,ps);}return ps;}
function workshop(){const ps=projects();const cur=ps.list.find(x=>x.id===ps.current)||ps.list[0];
 return shell(`<section class="ws-head"><div><div class="eyebrow">${t('FREE WORKSHOP')}</div><h1>${t('Build anything.')}</h1><p>${t('Your own projects: write code, add parts from “+ Add part”, drag a wire from pin to pin and press Run. Projects are saved in this browser.')}</p></div>
  <div class="ws-bar"><label class="sr-only" for="ws-project">${t('Project')}</label><select id="ws-project" class="select">${ps.list.map(x=>`<option value="${x.id}" ${x.id===cur.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>
  <button class="secondary" id="ws-new">${t('New')}</button><button class="secondary" id="ws-rename">${t('Rename')}</button><select id="ws-example" class="select" aria-label="${t('Open an example')}"><option value="">${t('Examples…')}</option>${Object.values(MISSIONS).filter(m=>RELEASED_UNITS.includes(allLessons.find(l=>l.id===m.id)?.unit)).map(m=>`<option value="${m.id}">${esc(M(m.id).title)}</option>`).join('')}</select>
  <button class="secondary" id="ws-export">${t('Export')}</button><button class="secondary" id="ws-import">${t('Import')}</button><button class="secondary" id="ws-delete">${t('Delete')}</button><input class="sr-only" type="file" id="ws-file" accept="application/json,.json" aria-label="${t('Project file')}"></div></section>
  <div id="lab-root" class="ws-lab"></div>`,true);}
function mountWorkshopLab(){const ps=projects();const cur=ps.list.find(x=>x.id===ps.current)||ps.list[0];lab?.destroy();
 lab=new Lab({t,code:cur.code,diagram:cur.diagram,onChange:st=>{const all=projects();const it=all.list.find(x=>x.id===cur.id);if(it){it.code=st.code;it.diagram=st.diagram;it.updated=Date.now();store(PROJ_KEY,all);}}});lab.mount($('#lab-root'));}
function bindWorkshop(){const ps=projects();const save=()=>{store(PROJ_KEY,ps);render();};
 $('#ws-project').onchange=e=>{ps.current=e.target.value;save();};
 $('#ws-new').onclick=()=>{const n=blankProject();ps.list.push(n);ps.current=n.id;save();};
 $('#ws-rename').onclick=()=>{const cur=ps.list.find(x=>x.id===ps.current);const name=prompt(t('Project name'),cur.name);if(name&&name.trim()){cur.name=name.trim().slice(0,60);save();}};
 $('#ws-delete').onclick=()=>{if(ps.list.length<2){toast(t('Keep at least one project.'));return;}if(!confirm(t('Delete this project?')))return;ps.list=ps.list.filter(x=>x.id!==ps.current);ps.current=ps.list[0].id;save();};
 $('#ws-example').onchange=e=>{const m=MISSIONS[e.target.value];if(!m)return;const n={...blankProject(),name:M(m.id).title,code:sk(m.solution.code),diagram:m.solution.diagram};ps.list.push(n);ps.current=n.id;save();toast(t('Example opened as a new project.'));};
 $('#ws-export').onclick=()=>{const cur=ps.list.find(x=>x.id===ps.current);download(cur.name.replace(/[^\w-]+/g,'_')+'.pinbypin.json',JSON.stringify({format:'pin-by-pin-project',version:1,name:cur.name,code:cur.code,diagram:cur.diagram},null,1),'application/json');};
 $('#ws-import').onclick=()=>$('#ws-file').click();
 $('#ws-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=JSON.parse(await f.text());if(v.format!=='pin-by-pin-project'||typeof v.code!=='string'||!Array.isArray(v.diagram?.parts))throw 0;const n={...blankProject(),name:String(v.name||'Imported').slice(0,60),code:v.code,diagram:v.diagram};ps.list.push(n);ps.current=n.id;save();}catch{toast(t('This is not a Pin by Pin Lab project file.'));}};}
// ---------- render / routing ----------
function focusKey(el){if(!el||el===document.body||!app.contains(el)||el.closest('#lab-root'))return null;if(el.id)return '#'+el.id;for(const a of ['data-choice','data-cp-choice','data-cp-input','data-lang','data-lesson','data-nav'])if(el.hasAttribute(a))return `[${a}="${el.getAttribute(a)}"]`;return null;}
function render(focus=false){const key=focus?null:focusKey(document.activeElement);lab?.destroy();lab=null;
 app.innerHTML=view==='home'?home():view==='notebook'?notebook():view==='workshop'?workshop():lessonPage();bind();
 if(view==='workshop'){mountWorkshopLab();bindWorkshop();}if(view==='lesson'&&lesson.type==='mission')mountMissionLab();
 if(focus){window.scrollTo(0,0);document.querySelector('.focus-title')?.focus();}else if(key)document.querySelector(key)?.focus({preventScroll:true});}
const routes={home:'#/',workshop:'#/workshop',notebook:'#/notebook'},aliases={'#/atolye':'workshop','#/defter':'notebook'};
function go(hash){if(location.hash===hash)route();else location.hash=hash;}
function route(){const m=location.hash.match(/^#\/(?:lesson|ders)\/([\w-]+)$/);if(m){if(canOpen(m[1],p)){start(m[1]);return;}history.replaceState(null,'','#/');}show(Object.keys(routes).find(k=>routes[k]===location.hash)||aliases[location.hash]||'home');}
function navigate(v){go(routes[v]||'#/');}
function openLesson(id){go('#/lesson/'+id);}
function show(v){view=v;render(true);}
function start(id){lesson=lessons.find(l=>l.id===id);view='lesson';selected=null;checked=false;hint=false;cps={answers:{},graded:false};ms={hints:0,passed:null,done:false};render(true);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function finish(){const already=p.completed.includes(lesson.id),c=lesson.type==='mission'?null:L(lesson);lab?.destroy();lab=null;p=complete(p,lesson.id,today());save();const next=nextLesson(p);
 const head=lesson.type==='checkpoint'?t('Unit {u} passed.',{u:lesson.unit}):lesson.type==='mission'?t('It works!'):t('Now you know this.');
 const body=lesson.type==='quiz'?esc(c.explanation):lesson.type==='checkpoint'?(RELEASED_UNITS.includes(lesson.unit+1)?t('Every lesson of this unit is open now, and so is the next unit.'):t('Every lesson of this unit is open now.')):t('Your circuit and your code reached every goal. Your work stays saved in this project.');
 app.innerHTML=`<main id="main" class="success"><div class="success-mark">✓</div><div class="eyebrow" style="margin-top:25px">${t('ONE MORE STEP DONE')}</div><h1>${head}</h1><p>${t('You completed {title}.',{title:esc(title(lesson))})}<br>${body}</p><div class="earned">${already?t('COMPLETED AGAIN'):t('COMPLETED')} &nbsp; / &nbsp; ${p.completed.length} / ${lessons.length} ${t('TASKS')}</div><div class="success-actions"><button class="secondary" data-nav="home">${t('Back to the learning path')}</button>${next?`<button class="primary" data-lesson="${next.id}">${t('Next step ↗')}</button>`:`<button class="primary" data-nav="workshop">${t('Explore the workshop ↗')}</button>`}</div></main>`;bind();window.scrollTo(0,0);announce(t('Task completed.'));}
function bind(){document.querySelectorAll('[data-home]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate('home');});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.choice);render();});
 $('#hint')?.addEventListener('click',()=>{hint=!hint;$('#hint-text').hidden=!hint;$('#hint').setAttribute('aria-expanded',String(hint));$('#hint').textContent=t('A small hint')+' '+(hint?'−':'+');});
 $('#check-answer')?.addEventListener('click',()=>{const c=L(lesson);if(checked){finish();return;}if(selected===lesson.answer){checked=true;render();announce(t('Correct.')+' '+c.explanation);}else{const f=$('#feedback');f.className='feedback bad';f.textContent=t('Not yet. {hint} You can try another answer.',{hint:c.hint});}});
 document.querySelectorAll('[data-cp-choice]').forEach(b=>b.onclick=()=>{const [i,n]=b.dataset.cpChoice.split('-').map(Number);cps.answers[i]=n;render();});
 const cpReady=()=>{const b=$('#cp-submit');if(b&&!cps.graded)b.disabled=lesson.questions.some((q,i)=>String(cps.answers[i]??'').trim()==='');};
 document.querySelectorAll('[data-cp-input]').forEach(el=>el.addEventListener('input',()=>{cps.answers[Number(el.dataset.cpInput)]=el.value;cpReady();}));cpReady();
 $('#cp-submit')?.addEventListener('click',()=>{if(!cps.graded){cps.graded=true;render();$('#feedback')?.scrollIntoView({block:'center'});announce($('#feedback').textContent);return;}const res=grade(lesson.questions,cps.answers);if(res.filter(Boolean).length>=lesson.pass){finish();return;}res.forEach((ok,i)=>{if(!ok)delete cps.answers[i];});cps.graded=false;render();window.scrollTo(0,0);});
 $('#mission-done')?.addEventListener('click',()=>{if(ms.done)finish();});
 $('#hint-next')?.addEventListener('click',e=>{const c=M(lesson.id);if(ms.hints>=c.hints.length)return;ms.hints++;$('#hints').innerHTML=c.hints.slice(0,ms.hints).map(h=>`<p class="hint-text">${md(h)}</p>`).join('');e.currentTarget.textContent=t('Show a hint ({i} / {n})',{i:Math.min(ms.hints+1,c.hints.length),n:c.hints.length});e.currentTarget.disabled=ms.hints>=c.hints.length;announce(c.hints[ms.hints-1]);});
 $('#show-solution')?.addEventListener('click',()=>{if(!confirm(t('Replace your code and circuit with the solution?')))return;const m=MISSIONS[lesson.id];saveWork(lesson.id,{code:sk(m.solution.code),diagram:m.solution.diagram});mountMissionLab();toast(t('Solution loaded. Press ▶ Run to see it work.'));});
 $('#reset-work')?.addEventListener('click',()=>{if(!confirm(t('Start this project again from the beginning?')))return;const all=load(WORK_KEY,{});delete all[lesson.id];store(WORK_KEY,all);mountMissionLab();});
 $('#export-progress')?.addEventListener('click',()=>download(t('pin-by-pin-notebook.json'),JSON.stringify(p,null,2),'application/json'));$('#import-progress')?.addEventListener('click',()=>$('#progress-file').click());
 $('#progress-file')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw new Error();const value=JSON.parse(await f.text());if(value.version!==1||!Array.isArray(value.completed)||!Array.isArray(value.dates))throw new Error();const imported=sanitizeProgress(value);p=sanitizeProgress({completed:[...p.completed,...imported.completed],dates:[...p.dates,...imported.dates]});save();render();toast(t('Notebook merged into your current progress.'));}catch{toast(t('This file is not a valid Pin by Pin Lab notebook.'));}});
 $('#reset-progress')?.addEventListener('click',()=>{if(confirm(t('Your progress in this browser will be reset. Do you want to continue?'))){p=sanitizeProgress({});save();render();}});}
window.addEventListener('hashchange',route);applyLang();route();
